def comp_cells(g,col,conn8=True):
    R,C=len(g),len(g[0]); seen=set(); out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]==col and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            if dy==0 and dx==0: continue
                            if not conn8 and abs(dy)+abs(dx)!=1: continue
                            ny,nx=y+dy,x+dx
                            if 0<=ny<R and 0<=nx<C and g[ny][nx]==col and (ny,nx) not in seen:
                                seen.add((ny,nx)); st.append((ny,nx))
                out.append(frozenset(comp))
    return out

